// The register entry required by Regulation respecting confidentiality incidents, s. 7, plus checks and next steps.
const f = $input.first().json;
const today = $now.startOf('day');
const errors = [];
if (f.incident_to && f.incident_to < f.incident_from) errors.push('the end of the period is before its start');
if (f.became_aware_on < f.incident_from) errors.push('the business cannot become aware of an incident before it started');
if (f.became_aware_on > today.toISODate()) errors.push('the awareness date is in the future');
if (Number(f.persons_concerned) < 0) errors.push('the number of persons cannot be negative');
if (errors.length) throw new Error(errors.map(e => e[0].toUpperCase() + e.slice(1)).join('. ') + '.');

const serious = f.decision.startsWith('Yes');
const high = [f.sensitivity, f.consequences, f.likelihood].filter(v => v === 'High').length;
const warnings = [];
if (f.consulted !== 'Yes') warnings.push('The person in charge of the protection of personal information must be consulted when assessing the risk (s. 3.7).');
if (!serious && high >= 2) warnings.push('Two or more factors are rated High but the conclusion is "no risk of serious injury". Check the reasoning with the person in charge.');
if (f.decision === 'Not yet assessed') warnings.push('The risk is not assessed yet. The daily reminder will list this incident until it is.');

const id = 'INC-' + today.toFormat('yyyyLLdd') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
const categories = Array.isArray(f.info_categories) ? f.info_categories.join(', ') : String(f.info_categories);
return [{ json: {
  incident_id: id,
  recorded_on: today.toISODate(),
  recorded_by: f.user?.email || '',
  incident_type: f.incident_type,
  information_concerned: categories + ' - ' + f.info_details.trim(),
  circumstances: f.circumstances.trim(),
  incident_from: f.incident_from,
  incident_to: f.incident_to || '',
  incident_dates_approximate: f.dates_approximate,
  became_aware_on: f.became_aware_on,
  persons_concerned: Number(f.persons_concerned),
  persons_approximate: f.persons_approximate,
  sensitivity: f.sensitivity,
  anticipated_consequences: f.consequences,
  likelihood_of_injurious_use: f.likelihood,
  risk_reasoning: f.risk_reasoning.trim(),
  person_in_charge_consulted: f.consulted,
  risk_of_serious_injury: f.decision,
  measures_to_reduce_risk: f.measures.trim(),
  cai_notified_on: '', persons_notified_on: '', public_notice: '', person_notice_delay_reason: '',
  status: serious ? 'notices due' : (f.decision === 'Not yet assessed' ? 'to assess' : 'recorded'),
  keep_until: DateTime.fromISO(f.became_aware_on).plus({ years: 5 }).toISODate(),
  _warnings: warnings,
  _serious: serious,
} }];

// Drop the helper fields (_warnings, _serious) before saving.
const e = $('Build register entry').first().json;
return [{ json: Object.fromEntries(Object.entries(e).filter(([k]) => !k.startsWith('_'))) }];

// The confirmation page: reference, warnings, and what the law asks next.
const e = $('Build register entry').first().json;
const li = a => a.map(x => '<li>' + x + '</li>').join('');
let html = '<h2>Incident recorded</h2><p>Reference: <b>' + e.incident_id + '</b>. Keep this entry until ' + e.keep_until + ' (5 years after the business became aware of it, Regulation respecting confidentiality incidents, s. 8).</p>';
if (e._warnings.length) html += '<h3>Check</h3><ul>' + li(e._warnings) + '</ul>';
if (e._serious) html += '<h3>Risk of serious injury: notify promptly (s. 3.5)</h3><p>The Act sets no number of days: it says promptly (« avec diligence »). Notify the Commission d\'accès à l\'information and every person whose information is concerned, then record the dates with the second form.</p>'
  + '<p>The notice to the Commission includes, among other things: your business name and NEQ, a contact person, the information concerned, the circumstances and cause, the dates, the number of persons concerned and how many live in Québec, why there is a risk of serious injury, and the measures taken or planned (Regulation s. 3).</p>'
  + '<p>The notice to each person includes: the information concerned, the circumstances, the dates, the measures you took, the measures you suggest to them, and a contact (Regulation s. 5).</p>';
html += '<p>Whatever the risk, keep taking reasonable measures to reduce the risk of injury and prevent new incidents of the same nature (s. 3.5).</p>';
return [{ json: { html } }];

// Merge the update into the entry. Refuse to close an incident whose required notices are missing.
const f = $('Staff: record notices and close').first().json;
const row = $input.all().map(i => i.json).find(r => r.incident_id);
if (!row) throw new Error('No incident with reference "' + f.incident_id + '" in the register.');
const pick = (v, old) => (v === undefined || v === null || String(v).trim() === '') ? old : String(v).trim();
const u = {
  risk_of_serious_injury: f.decision === 'Keep current conclusion' ? row.risk_of_serious_injury : f.decision,
  cai_notified_on: pick(f.cai_notified_on, row.cai_notified_on),
  persons_notified_on: pick(f.persons_notified_on, row.persons_notified_on),
  public_notice: pick(f.public_notice, row.public_notice),
  person_notice_delay_reason: pick(f.delay_reason, row.person_notice_delay_reason),
  measures_to_reduce_risk: f.more_measures && f.more_measures.trim()
    ? row.measures_to_reduce_risk + '\n[' + $now.toISODate() + '] ' + f.more_measures.trim() : row.measures_to_reduce_risk,
};
for (const k of ['cai_notified_on', 'persons_notified_on'])
  if (u[k] && u[k] < row.became_aware_on) throw new Error((k === 'cai_notified_on' ? 'The Commission notice date' : 'The persons notice date') + ' is before the business became aware of the incident.');
const serious = u.risk_of_serious_injury.startsWith('Yes');
const missing = [];
if (serious && !u.cai_notified_on) missing.push('the date the Commission was notified');
if (serious && !u.persons_notified_on && !u.public_notice && !u.person_notice_delay_reason) missing.push('the date the persons were notified (or a public notice, or the investigation delay)');
if (u.risk_of_serious_injury === 'Not yet assessed') missing.push('a conclusion on the risk of serious injury');
if (f.close === 'Yes' && missing.length) throw new Error('The incident cannot be closed yet. Missing: ' + missing.join('; ') + '.');
u.status = f.close === 'Yes' ? 'closed' : (serious && missing.length ? 'notices due' : (u.risk_of_serious_injury === 'Not yet assessed' ? 'to assess' : 'recorded'));
u._incident_id = row.incident_id;
u._html = '<h2>Register updated</h2><p>' + row.incident_id + ': status <b>' + u.status + '</b>.</p>'
  + (missing.length ? '<p>Still missing: ' + missing.join('; ') + '.</p>' : '')
  + '<p>Keep this entry until ' + row.keep_until + '.</p>';
return [{ json: u }];

// Notices still due, risk still unassessed, entries past their retention date. No item, no email.
const s = $('Settings').first().json;
const today = $now.startOf('day');
const rows = $input.all().map(i => i.json).filter(r => r.incident_id);
const days = r => Math.round(today.diff(DateTime.fromISO(r.became_aware_on), 'days').days);
const notices = rows.filter(r => r.status === 'notices due');
const unassessed = rows.filter(r => r.status === 'to assess' && days(r) >= s.assess_within_days);
const expired = rows.filter(r => r.keep_until && r.keep_until < today.toISODate());
if (!notices.length && !unassessed.length && !expired.length) return [];
const line = r => '<li><b>' + r.incident_id + '</b> - ' + r.incident_type + ' - aware since ' + r.became_aware_on + ' (' + days(r) + ' days)</li>';
const section = (title, list) => list.length ? '<h3>' + title + '</h3><ul>' + list.map(line).join('') + '</ul>' : '';
return [{ json: {
  to: s.privacy_officer_email, from: s.from_email,
  subject: 'Law 25 incidents: ' + notices.length + ' with notices due, ' + unassessed.length + ' not assessed',
  html: section('Risk of serious injury - notices not yet recorded (notify promptly, s. 3.5)', notices)
      + section('Risk not assessed for ' + s.assess_within_days + ' days or more', unassessed)
      + section('Past the retention date (5 years) - review before deleting', expired),
} }];
